// appsettings.json
{
  "Smtp": { "Host": "smtp.example.com", "Port": 587 }
}

// Program.cs
using System.ComponentModel.DataAnnotations;
using Microsoft.Extensions.Options;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOptions<SmtpOptions>()
    .BindConfiguration("Smtp")       // секция "Smtp" -> класс
    .ValidateDataAnnotations()       // проверить атрибуты
    .ValidateOnStart();              // и сделать это при старте
builder.Services.AddSingleton<Mailer>();

var app = builder.Build();
app.Run();

public sealed class SmtpOptions
{
    [Required] public string Host { get; set; } = "";
    [Range(1, 65535)] public int Port { get; set; }
}

public sealed class Mailer(IOptions<SmtpOptions> options)
{
    private readonly SmtpOptions _smtp = options.Value;
}

using Testcontainers.PostgreSql;
using Xunit;

// Одна база на все тесты класса: старт контейнера стоит секунды
public sealed class DbFixture : IAsyncLifetime
{
    public PostgreSqlContainer Db { get; } = new PostgreSqlBuilder()
        .WithImage("postgres:17")
        .Build();

    public Task InitializeAsync() => Db.StartAsync();
    public Task DisposeAsync() => Db.DisposeAsync().AsTask();
}

public class OrderRepoTests(DbFixture fx) : IClassFixture<DbFixture>
{
    [Theory]
    [InlineData(1, 100)]
    [InlineData(3, 300)]
    [Trait("Category", "Integration")]
    public async Task Total_SeveralItems_ReturnsSum(int count, int expected)
    {
        // Arrange
        var repo = new OrderRepo(fx.Db.GetConnectionString());
        await repo.CreateSchemaAsync();
        var id = await repo.CreateOrderAsync(Enumerable.Repeat(100, count));

        // Act
        var total = await repo.TotalAsync(id);

        // Assert
        Assert.Equal(expected, total);
    }
}
